                                    x_o, y_o = (w_o-lado_o)//2, (h_o-lado_o)//2
                                    imagen_editada = imagen_editada.crop((x_o, y_o, x_o+lado_o, y_o+lado_o))
                                    acciones_orden.append("recorte cuadrado")
