                    prioridad=prioridad_presupuesto,
                    alcance=("Una sola oferta; no hay comparación entre proveedores" if len(st.session_state["presu_resultados"]) == 1 else alcance_presupuestos),
                    tipo_trabajo=tipo_obra_presupuesto,
